mapper.sql:
from audit_change_log
where tenant_id = #{tenantId}

  and biz_type = #{bizType}


  and biz_type like concat(#{bizTypePrefix}, '%')


  and biz_id = #{bizId}


  and action = #{action}


  and operator_name like concat('%', #{operatorName}, '%')


  and operated_at >= #{startTime}


  and operated_at <= #{endTime}

mapper.select:
select 

order by operated_at desc, id desc
limit #{limit} offset #{offset}
